def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

sum_of_primes = 0
for number in range(2, 10000):
    if is_prime(number):
        sum_of_primes += number

print(f"ผลรวมของจำนวนเฉพาะที่น้อยกว่า 10000 คือ: {sum_of_primes}")

